use xiom.io;

enum Mood {
  Happy,
  Sad,
  Excited,
  Tired,
  Hungry,
}

fn Mood.emoji(self) -> Str {
  match self {
    Happy => { return "\xF0\x9F\x98\x8A"; }
    Sad => { return "\xF0\x9F\x98\xA2"; }
    Excited => { return "\xF0\x9F\xA4\xA9"; }
    Tired => { return "\xF0\x9F\x98\xB4"; }
    Hungry => { return "\xF0\x9F\x8D\x94"; }
  }
}

fn Mood.label(self) -> Str {
  match self {
    Happy => { return "Feeling great"; }
    Sad => { return "Feeling down"; }
    Excited => { return "Can't wait"; }
    Tired => { return "Need rest"; }
    Hungry => { return "Need food"; }
  }
}

fn Mood.energy_level(self) -> Int {
  match self {
    Happy => { return 7; }
    Sad => { return 2; }
    Excited => { return 10; }
    Tired => { return 1; }
    Hungry => { return 3; }
  }
}

fn main() -> Int {
  let m1 = Mood.Happy;
  let m2 = Mood.Sad;
  let m3 = Mood.Excited;
  let m4 = Mood.Tired;
  let m5 = Mood.Hungry;
  return m1.energy_level() + m2.energy_level() + m3.energy_level() + m4.energy_level() + m5.energy_level();
}
